const words = puzzle.split(/==|===/)[0].split('+').map(w => w.trim()).concat(puzzle.split(/==|===/)[1].trim());
const letters = [...new Set(words.flatMap(w => w.split('').filter(c => c !== ' ')))];
if (letters.length > 10) return undefined;
const wordValues = words.map(w => w.split('').map(c => letters.indexOf(c))).map(col => col.map((_, i) => Math.pow(10, col.length - 1 - i)).reduce((a, b) => a + b, 0));
const leadingLetters = new Set(words.map(w => w[0]));
const permutations = [];
const permute = (arr, start = 0) => {
  if (start === arr.length) permutations.push([...arr]);
  else for (let i = start; i < arr.length; i++) {
    [arr[start], arr[i]] = [arr[i], arr[start]];
    permute(arr, start + 1);
    [arr[start], arr[i]] = [arr[i], arr[start]];
  }
};
permute([...letters]);
for (const p of permutations) {
  if (p.some((v, i) => leadingLetters.has(letters[i]) && v === 0)) continue;
  const mapping = {};
  for (let i = 0; i < letters.length; i++) mapping[letters[i]] = p[i];
  const sum = wordValues.map((w, i) => w.map((_, j) => mapping[letters[i * letters.length + j]]).reduce((a, b) => a + b, 0));
  if (sum === 0) return mapping;
}
return undefined;

